{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello, आपको pneumatic pouch packing machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी Ma'am।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "बताइए capacity में क्या prefer करेंगे 1000 pouch hour, 2000 pouch hour या कोई और?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "1000."
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "ठीक है, अब machine type के बारे में बात कर लेते हैं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको automatic, semi-automatic या कुछ और चाहिए?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "automatic."
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "आप अपनी city और state भी बता दीजिए please।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "[change] अंबिकापुर छत्तीसगढ़।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आप अंबिकापुर छत्तीसगढ़ से बोल रहे हैं ना?"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आप अपना नाम भी बता दीजिए।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "बता दीजिए please."
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "सत्येंद्र साहब।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "ये आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "Thank you."
    }
  ]
}
